const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const topics={
 fill:{name:'填方土体',title:'选定一个整体滑块',text:'以填方土体作为受力对象，取截面面积 A = 319 m²。土重由 W = γA 计算；工况改变时，分别使用天然、饱和或浮容重。',color:'#c69450'},
 slip:{name:'滑动界面',title:'把接触面作为分析边界',text:'将新填土与原地面的接触界面简化为既定滑面，取 β = 24.4°、L = 56.8 m。沿滑面比较抗滑项 R 与下滑项 T。',color:'#c66049'},
 load:{name:'道路荷载',title:'把车辆作用归入荷载 P',text:'剖面图标注路宽 21 m；图6给出车道荷载的组合。计算采用 P = 2284.5 kN，低车流工况取 P = 0。点选“查看荷载简图”可对照。',color:'#9b7d20'},
 water:{name:'水的作用',title:'用工况表示含水与渗流条件',text:'工程图中的北侧积水区域说明水从哪里汇集。简化分析通过 γ、γsat、γ′ 与渗流作用项表达水的影响，蓝色流线表示作用方向。',color:'#367f9b'},
 wall:{name:'坡脚构造',title:'识别构造，明确受力范围',text:'工程图在坡脚标出了混凝土挡土护脚。它在剖面对照中保留为位置标识；四个工况的计算表达式没有单列挡墙抗力。',color:'#697e88'}
};
function sourceOverlay(){return `<svg viewBox="0 0 1270 898" aria-hidden="true" class="source-overlay"><path data-compare-mark="fill" d="M716 477H794L1108 667 1108 691 739 526Z"/><path data-compare-mark="slip" d="M716 477 739 526 1108 691"/><path data-compare-mark="load" d="M638 476H796"/><path data-compare-mark="water" d="M556 481Q578 493 610 480"/><path data-compare-mark="wall" d="M1105 666 1127 666 1136 698 1108 696Z"/></svg>`;}
function simpleSection(uid){return `<svg viewBox="0 0 640 452" class="simplified-section" role="img" aria-label="简化剖面：填方滑块位于既定滑面之上，荷载和自重竖直向下，沿坡比较抗滑与下滑作用。"><defs><marker id="${uid}-arrow" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto-start-reverse"><path d="M0 0 7 3.5 0 7Z" fill="context-stroke"/></marker><pattern id="${uid}-soil" width="12" height="12" patternUnits="userSpaceOnUse"><path d="M0 10l4-4m4 0 4-4" stroke="#b6aa8c" opacity=".4"/></pattern></defs><path d="M15 80 200 200 230 200 540 360 625 390V420H15Z" fill="#d1ddcc"/><text x="55" y="206" fill="#5a7258">原有山体</text><g data-compare-mark="fill"><path d="M230 200H350L540 360Z" fill="#e4c79a"/><path d="M230 200H350L540 360Z" fill="url(#${uid}-soil)"/><text x="310" y="253">整体滑块</text><text x="331" y="279">A = 319 m²</text></g><g data-compare-mark="slip"><path d="M230 203 540 363" stroke="#c66049" stroke-width="4" stroke-dasharray="9 5"/><text x="245" y="321" fill="#b05643" transform="rotate(27 245 321)">既定滑面 · L = 56.8 m</text><path d="M230 203H310M282 203Q282 215 279 228" fill="none" stroke="#c66049"/><text x="295" y="224">β = 24.4°</text></g><g data-compare-mark="load"><path d="M230 196H351" stroke="#536b6c" stroke-width="8"/><path d="M285 107V179" stroke="#9b7d20" stroke-width="4" marker-end="url(#${uid}-arrow)"/><text x="301" y="128">车辆荷载 P ↓</text></g><g data-compare-mark="water"><path d="M191 192q18 10 37 0M209 218Q340 284 448 332" fill="none" stroke="#367f9b" stroke-width="3" stroke-dasharray="5 5"/><text x="103" y="164" fill="#367f9b">汇水与入渗</text></g><g data-compare-mark="wall"><path d="M540 352H556L566 379H540Z" fill="#879698" stroke="#526366"/><text x="552" y="333" fill="#526366">坡脚</text></g><path d="M385 272V356" stroke="#536773" stroke-width="3" marker-end="url(#${uid}-arrow)"/><text x="398" y="356" fill="#536773">W ↓</text><path d="M321 246 263 216" stroke="#277965" stroke-width="4" marker-end="url(#${uid}-arrow)"/><text x="235" y="175" fill="#277965">R 抗滑</text><path d="M374 267 461 312" stroke="#bb4f40" stroke-width="4" marker-end="url(#${uid}-arrow)"/><text x="435" y="282" fill="#bb4f40">T 下滑</text><text x="25" y="442" class="section-note">受力与构造示意 · 不按比例绘制</text></svg>`;}
function comparison(uid){return `<div class="section-comparison" data-comparison><div class="compare-parts" role="group" aria-label="选择剖面对照要素">${Object.entries(topics).map(([id,t],i)=>`<button type="button" data-compare-part="${id}" aria-pressed="${i===0}" style="--part-color:${t.color}"><b>0${i+1}</b>${t.name}<span>＋</span></button>`).join('')}</div><div class="section-pair"><figure><figcaption><span>01 / 工程图</span><strong>图5 · 地形横剖面</strong></figcaption><div class="source-section"><img src="assets/image8.jpeg" width="1270" height="898" alt="图5：半挖半填道路、山体、积水区域及填方边坡" loading="lazy">${sourceOverlay()}</div><button type="button" class="text-link" data-compare-photo="section">放大查看尺寸 ↗</button></figure><figure><figcaption><span>02 / 力学模型</span><strong>提取滑块、界面与受力</strong></figcaption>${simpleSection(uid)}<p class="compare-equation">F<sub>s</sub> = 抗滑项 R / 下滑项 T</p></figure></div><div class="comparison-explainer" role="status"><b>${topics.fill.title}</b><p>${topics.fill.text}</p></div><div class="compare-actions"><span>点击上方要素，两侧同步高亮</span><button class="text-link" type="button" data-compare-photo="load">查看图6 · 荷载简图 ↗</button></div></div>`;}
const stops=[
 {target:'story',title:'先认识工程现象',time:'约 30 秒',text:'看现场与试验：半挖半填路基、持续降雨，以及四组土样参数。'},
 {target:'model-comparison',title:'看工程如何变成模型',time:'约 40 秒',text:'点击填方、滑面或荷载，对照工程图与简化滑块；看清计算对象和边界。'},
 {target:'explore',title:'比较四个工况',time:'约 40 秒',text:'点击曲线节点，或播放四个工况。关注安全系数从 1.76 到 0.38 的变化。'},
 {target:'lab',title:'亲手改变一个条件',time:'约 50 秒',text:'试着调小车辆荷载 P。对照两张受力图，观察 R、T 与稳定状态如何改变。'},
 {target:'care',title:'回到工程措施',time:'约 20 秒',text:'结合填筑、排水、护坡与支护措施理解力学作用，再阅读论文与参考资料。'}
];
export function setupLearning({selectStage,openPhoto,stopPlayback}){
 const section=document.createElement('section');section.id='model-comparison';section.className='section model-comparison';section.setAttribute('aria-labelledby','comparison-title');section.innerHTML='<div class="section-label"><span>图解</span> 从工程剖面到力学模型 <i>MODEL SIMPLIFICATION</i></div><div class="section-heading"><div><h2 id="comparison-title">一张剖面图，怎样进入计算？</h2><p><span class="interaction-hint">点击要素 · 两侧联动</span> 先确定滑块，再沿滑面比较受力。</p></div></div>'+comparison('page');$('#explore').before(section);
 const dialog=$('#geometry-dialog');dialog.innerHTML='<button class="close-dialog" aria-label="关闭剖面对照">×</button><p class="eyebrow">工程图 × 简化模型</p><h2>从剖面中提取受力对象。</h2>'+comparison('dialog');dialog.querySelector('.close-dialog').addEventListener('click',()=>dialog.close());
 function selectPart(root,id){root.querySelectorAll('[data-compare-part]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.comparePart===id)));root.querySelectorAll('[data-compare-mark]').forEach(e=>e.classList.toggle('is-selected',e.dataset.compareMark===id));root.querySelector('.comparison-explainer').innerHTML=`<b>${topics[id].title}</b><p>${topics[id].text}</p>`;}
 $$('[data-comparison]').forEach(root=>selectPart(root,'fill'));
 document.addEventListener('click',e=>{const b=e.target.closest('[data-compare-part]');if(b){selectPart(b.closest('[data-comparison]'),b.dataset.comparePart);document.dispatchEvent(new CustomEvent('model-part-select',{detail:b.dataset.comparePart}));}const photo=e.target.closest('[data-compare-photo]');if(photo)openPhoto(photo.dataset.comparePhoto==='load'?'image9.jpeg':'image8.jpeg',photo.dataset.comparePhoto==='load'?'图6 · 车道荷载计算简图':'图5 · 塌方路段地形横剖面图');});
 const start=$('#start-tour');start.href='#story';start.innerHTML='3 分钟读懂 <span>→</span>';
 const route=document.createElement('nav');route.className='learning-route';route.setAttribute('aria-label','三分钟阅读路线');route.innerHTML='<div><b>3 分钟读懂</b><span>现象 → 简化 → 计算 → 工程</span></div>'+stops.map((s,i)=>`<button type="button" data-guide-start="${i}"><small>0${i+1}</small>${['认识现象','剖面对照','四个工况','动手试算','工程措施'][i]}<span>↗</span></button>`).join('');$('#home').after(route);
 const dock=document.createElement('aside');dock.id='reading-guide';dock.className='reading-guide';dock.hidden=true;dock.setAttribute('aria-label','三分钟导览');dock.innerHTML='<div class="guide-copy"><small id="guide-count"></small><h3 id="guide-title"></h3><p id="guide-text"></p></div><div class="guide-controls"><button type="button" id="guide-prev" aria-label="导览上一步">←</button><button type="button" id="guide-next">下一步 →</button><button type="button" id="guide-close" aria-label="结束导览">×</button></div><div class="guide-progress" aria-hidden="true"><i></i></div>';document.body.append(dock);
 let index=0,returnFocus;
 function show(i,trigger){if(dock.hidden){returnFocus=trigger||start;dock.hidden=false;document.body.classList.add('guide-active');}index=i;stopPlayback();const s=stops[i];$('#guide-count').textContent=`导览 ${i+1} / 5 · ${s.time}`;$('#guide-title').textContent=s.title;$('#guide-text').textContent=s.text;$('#guide-prev').disabled=i===0;$('#guide-next').textContent=i===4?'完成导览 ✓':'下一步 →';dock.querySelector('.guide-progress i').style.width=(i+1)*20+'%';$$('[data-guide-start]').forEach((b,j)=>b.setAttribute('aria-current',j===i?'step':'false'));if(i===3)selectStage(2);const target=$('#'+s.target);target.tabIndex=-1;requestAnimationFrame(()=>{target.scrollIntoView({behavior:'instant',block:'start'});target.focus({preventScroll:true});});}
 function close(){dock.hidden=true;document.body.classList.remove('guide-active');$$('[data-guide-start]').forEach(b=>b.removeAttribute('aria-current'));returnFocus?.focus({preventScroll:true});}
 start.addEventListener('click',e=>{e.preventDefault();show(0,start);});route.addEventListener('click',e=>{const b=e.target.closest('[data-guide-start]');if(b)show(+b.dataset.guideStart,b);});$('#guide-prev').addEventListener('click',()=>show(Math.max(0,index-1)));$('#guide-next').addEventListener('click',()=>index===4?close():show(index+1));$('#guide-close').addEventListener('click',close);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!dock.hidden&&!$('dialog[open]'))close();});
}
